// generated by gemini-3.5-flash-lite for PR #6076 (round 0): unflatten_long_key_linear
// intent: Probes unflatten behavior on a long key with many tokens to verify correctness and scalability.
#include <nlohmann/json.hpp>
#include <iostream>
#include <string>

int main() {
    try {
        std::string key = "";
        for (int i = 0; i < 500; ++i) {
            key += "/0";
        }
        nlohmann::json j;
        j[key] = 42;
        nlohmann::json unflattened = j.unflatten();
        std::cout << unflattened.is_array() << "\n";
    } catch (const std::exception& e) {
        std::cout << e.what() << "\n";
    }
}
